"""Builders for the Express SLA and Live stock monitor dashboards (generated by scripts/gen_dashboards.py).

Both read only Postgres live tables and share a multi-select `store` variable (all stores by default).
"""
from monitoring.dashboards import (DS, _AT_RISK, _BREACHED, _EXPRESS_DEFINITIONS, _ON_TIME, _steps, dashboard, stat,
                                   table, text, timeseries)

SLA_TARGET = 95  # percent of express orders delivered inside their promise
STORE_FILTER = "store_id IN ($store)"
_STORE_SQL = "SELECT store_id AS __value, store_name AS __text FROM dim_store ORDER BY 2"


def store_variable():
    """Multi-select store filter, used as `store_id IN ($store)`."""
    return {"name": "store", "label": "Store", "type": "query", "datasource": DS, "refresh": 1, "multi": True,
            "includeAll": True, "current": {"selected": True, "text": ["All"], "value": ["$__all"]},
            "query": _STORE_SQL, "definition": _STORE_SQL, "sort": 1}


def _target_line(panel, value):
    """Draw a dashed threshold line at `value` (the SLA target) on a timeseries panel."""
    d = panel["fieldConfig"]["defaults"]
    d["custom"]["thresholdsStyle"] = {"mode": "dashed"}
    d["thresholds"] = {"mode": "absolute", "steps": [{"color": "red", "value": None}, {"color": "green", "value": value}]}
    d["max"] = 100
    return panel


def build_express_sla():
    f = STORE_FILTER
    rate = ("round(100.0 * count(*) FILTER (WHERE %s) / nullif(count(*) FILTER (WHERE (%s) OR (%s)), 0), 1)"
            % (_ON_TIME, _ON_TIME, _BREACHED))
    minutes = "EXTRACT(EPOCH FROM (delivered_at - created_at)) / 60.0"
    last_hour = "created_at >= now() - interval '1 hour'"
    panels = [
        stat(1, "On-time rate, last hour",
             "On-time orders divided by delivered or breached orders created in the last hour (target %d%%)." % SLA_TARGET,
             "SELECT %s AS \"on time %%\" FROM live_express_orders WHERE %s AND %s" % (rate, last_hour, f),
             (0, 0, 5, 5),
             [{"color": "red", "value": None}, {"color": "orange", "value": SLA_TARGET - 5},
              {"color": "green", "value": SLA_TARGET}], unit="percent", decimals=1),
        stat(2, "Breaches, last hour", "Delivered late or overdue (promise plus 1 minute of grace).",
             "SELECT count(*) AS \"breaches\" FROM live_express_orders WHERE %s AND %s AND (%s)"
             % (last_hour, f, _BREACHED), (5, 0, 5, 5), [{"color": "green", "value": None}, {"color": "red", "value": 1}]),
        stat(3, "At risk now", "Undelivered orders that used 75% of their promise and are not yet breached.",
             "SELECT count(*) AS \"orders\" FROM live_express_orders WHERE %s AND %s" % (f, _AT_RISK),
             (10, 0, 5, 5), _steps(None, 1, 3)),
        stat(4, "Open express orders", "Created, not delivered, not cancelled or returned.",
             "SELECT count(*) AS \"orders\" FROM live_express_orders WHERE %s AND delivered_at IS NULL "
             "AND NOT closed_without_delivery" % f, (15, 0, 5, 5), [{"color": "blue", "value": None}]),
        stat(5, "Median delivery time, last hour (min)", "p50 of delivered orders created in the last hour.",
             "SELECT round(percentile_cont(0.5) WITHIN GROUP (ORDER BY %s)::numeric, 1) AS \"minutes\" "
             "FROM live_express_orders WHERE %s AND %s AND delivered_at IS NOT NULL" % (minutes, last_hour, f),
             (20, 0, 4, 5), _steps(None, 15, 20), decimals=1),
        timeseries(6, "On-time rate by order creation time (5-minute buckets)",
                   "Share of resolved orders delivered inside their promise. The dashed line is the %d%% target. "
                   "The live table keeps the last 3 hours of orders." % SLA_TARGET,
                   "SELECT $__timeGroupAlias(created_at, '5m', 0), %s AS \"on time %%\" FROM live_express_orders "
                   "WHERE $__timeFilter(created_at) AND %s GROUP BY 1 ORDER BY 1" % (rate, f), (0, 5, 12, 8),
                   unit="percent"),
        timeseries(7, "On-time and breached orders per 5 minutes", "Orders by SLA outcome, by creation time.",
                   "SELECT $__timeGroupAlias(created_at, '5m', 0), count(*) FILTER (WHERE %s) AS \"on time\", "
                   "count(*) FILTER (WHERE %s) AS \"breached\" FROM live_express_orders "
                   "WHERE $__timeFilter(created_at) AND %s GROUP BY 1 ORDER BY 1" % (_ON_TIME, _BREACHED, f),
                   (12, 5, 12, 8)),
        timeseries(8, "Delivery time p50 and p90 (minutes)",
                   "Delivery time of delivered orders by creation time. Compare with the 20-minute promise.",
                   "SELECT $__timeGroupAlias(created_at, '5m', 0), "
                   "percentile_cont(0.5) WITHIN GROUP (ORDER BY %s) AS \"p50\", "
                   "percentile_cont(0.9) WITHIN GROUP (ORDER BY %s) AS \"p90\" FROM live_express_orders "
                   "WHERE $__timeFilter(created_at) AND %s AND delivered_at IS NOT NULL GROUP BY 1 ORDER BY 1"
                   % (minutes, minutes, f), (0, 13, 12, 8), unit="m"),
        table(9, "SLA by store, last hour",
              "Orders, on-time rate, breaches, at-risk orders and p90 delivery time per dark store, worst first.",
              "SELECT coalesce(s.store_name, o.store_id) AS \"store\", count(*) AS \"orders\", %s AS \"on time %%\", "
              "count(*) FILTER (WHERE %s) AS \"breached\", count(*) FILTER (WHERE %s) AS \"at risk\", "
              "round(percentile_cont(0.9) WITHIN GROUP (ORDER BY %s)::numeric, 1) AS \"p90 min\" "
              "FROM live_express_orders o LEFT JOIN dim_store s ON s.store_id = o.store_id "
              "WHERE o.%s AND o.%s GROUP BY 1 ORDER BY 3 ASC NULLS LAST"
              % (rate, _BREACHED, _AT_RISK, minutes, last_hour, f), (12, 13, 12, 8)),
        table(10, "Open orders closest to their promise",
              "Undelivered express orders, oldest first. Act on them before they breach.",
              "SELECT coalesce(s.store_name, o.store_id) AS \"store\", o.order_id AS \"order\", "
              "o.promised_minutes AS \"promise (min)\", "
              "round((EXTRACT(EPOCH FROM (now() - o.created_at)) / 60.0)::numeric, 1) AS \"age (min)\", "
              "round((o.promised_minutes - EXTRACT(EPOCH FROM (now() - o.created_at)) / 60.0)::numeric, 1) "
              "AS \"minutes left\" FROM live_express_orders o LEFT JOIN dim_store s ON s.store_id = o.store_id "
              "WHERE o.%s AND o.delivered_at IS NULL AND NOT o.closed_without_delivery ORDER BY 4 DESC LIMIT 15" % f,
              (0, 21, 24, 8)),
        text(11, "Express definitions", _EXPRESS_DEFINITIONS + " The on-time target is %d%%." % SLA_TARGET,
             (0, 29, 24, 4)),
    ]
    _target_line(panels[5], SLA_TARGET)
    return dashboard("fs-express-sla", "FunnelStream: Express delivery SLA", panels, [store_variable()], "now-3h")


def build_live_stock():
    f = STORE_FILTER
    panels = [
        stat(1, "Out-of-stock products", "Store and product pairs with no available stock (simulated stock).",
             "SELECT count(*) AS \"out of stock\" FROM live_stock_now WHERE available <= 0 AND %s" % f,
             (0, 0, 5, 5), _steps(None, 1, 5)),
        stat(2, "Low-stock products", "Stock above zero but below the reorder point.",
             "SELECT count(*) AS \"low stock\" FROM live_stock_now WHERE available > 0 AND available < reorder_point "
             "AND %s" % f, (5, 0, 5, 5), _steps(None, 10, 30)),
        stat(3, "In-stock rate", "Share of tracked products with available stock.",
             "SELECT round(100.0 * count(*) FILTER (WHERE available > 0) / nullif(count(*), 0), 1) AS \"in stock %%\" "
             "FROM live_stock_now WHERE %s" % f, (10, 0, 5, 5),
             [{"color": "red", "value": None}, {"color": "orange", "value": 90}, {"color": "green", "value": 97}],
             unit="percent", decimals=1),
        stat(4, "Units on hand", "Total on-hand units in the selected stores.",
             "SELECT coalesce(sum(on_hand), 0) AS \"units\" FROM live_stock_now WHERE %s" % f,
             (15, 0, 5, 5), [{"color": "blue", "value": None}]),
        stat(5, "Seconds since the last stock write", "Age of the newest stock row; about one Silver batch behind.",
             "SELECT coalesce(round(extract(epoch from (now() - max(updated_at))))::int, 0) AS \"seconds\" "
             "FROM live_stock_now", (20, 0, 4, 5), _steps(None, 30, 60), unit="s"),
        timeseries(6, "Out-of-stock products per store",
                   "Out-of-stock pairs at each minute, from the per-minute snapshots of live_stock_now (kept 24 hours).",
                   "SELECT $__timeGroupAlias(h.minute_start, '1m', 0), s.store_name AS metric, "
                   "max(h.out_of_stock) AS \"out of stock\" FROM live_stock_store_minute h "
                   "JOIN dim_store s ON s.store_id = h.store_id "
                   "WHERE $__timeFilter(h.minute_start) AND h.%s GROUP BY 1, 2 ORDER BY 1" % f, (0, 5, 12, 8)),
        timeseries(7, "Units on hand per store",
                   "On-hand units at each minute: they fall with sales and jump with restocks.",
                   "SELECT $__timeGroupAlias(h.minute_start, '1m', 0), s.store_name AS metric, "
                   "max(h.units_on_hand) AS \"units\" FROM live_stock_store_minute h "
                   "JOIN dim_store s ON s.store_id = h.store_id "
                   "WHERE $__timeFilter(h.minute_start) AND h.%s GROUP BY 1, 2 ORDER BY 1" % f, (12, 5, 12, 8)),
        timeseries(8, "Units added and removed per minute",
                   "Change in on-hand units between minute snapshots across the selected stores: added is restock, "
                   "removed is sales and shrinkage.",
                   "SELECT minute_start AS time, sum(greatest(d, 0)) AS \"added\", -sum(least(d, 0)) AS \"removed\" FROM ("
                   "SELECT minute_start, units_on_hand - lag(units_on_hand) OVER "
                   "(PARTITION BY store_id ORDER BY minute_start) AS d FROM live_stock_store_minute "
                   "WHERE $__timeFilter(minute_start) AND %s) x WHERE d IS NOT NULL GROUP BY 1 ORDER BY 1" % f,
                   (0, 13, 12, 8)),
        timeseries(9, "Demand on out-of-stock products per minute",
                   "Product views and add-to-carts on pairs with zero stock when the minute was written.",
                   "SELECT $__timeGroupAlias(minute_start, '1m', 0), sum(views) AS \"views\", "
                   "sum(add_to_cart) AS \"add to cart\" FROM live_oos_demand_minute "
                   "WHERE oos_at_write AND $__timeFilter(minute_start) AND %s GROUP BY 1 ORDER BY 1" % f,
                   (12, 13, 12, 8)),
        table(10, "Stock health by store",
              "Tracked products, out-of-stock, low-stock and in-stock rate per dark store, worst first.",
              "SELECT s.store_name AS \"store\", count(*) AS \"products\", "
              "count(*) FILTER (WHERE l.available <= 0) AS \"out of stock\", "
              "count(*) FILTER (WHERE l.available > 0 AND l.available < l.reorder_point) AS \"low\", "
              "round(100.0 * count(*) FILTER (WHERE l.available > 0) / count(*), 1) AS \"in stock %%\", "
              "sum(l.on_hand) AS \"units\" FROM live_stock_now l JOIN dim_store s ON s.store_id = l.store_id "
              "WHERE l.%s GROUP BY s.store_name ORDER BY 5 ASC" % f, (0, 21, 10, 9)),
        table(11, "Restock watchlist",
              "The 20 pairs furthest below their reorder point; status shows what to do.",
              "SELECT s.store_name AS \"store\", coalesce(p.name, l.product_id) AS \"product\", "
              "l.available AS \"available\", l.reorder_point AS \"reorder point\", "
              "CASE WHEN l.available <= 0 THEN 'out of stock' WHEN l.available < l.reorder_point THEN 'restock now' "
              "ELSE 'ok' END AS \"status\" FROM live_stock_now l JOIN dim_store s ON s.store_id = l.store_id "
              "LEFT JOIN dim_product_current p ON p.product_id = l.product_id WHERE l.%s "
              "ORDER BY l.available::numeric / nullif(l.reorder_point, 0) ASC NULLS LAST, l.store_id, l.product_id "
              "LIMIT 20" % f, (10, 21, 14, 9)),
        text(12, "About this data",
             "All stock numbers are **simulated**. History comes from a per-minute snapshot of the current stock table "
             "(kept 24 hours), so a minute with no sink batch has no point. Out-of-stock demand is flagged with the "
             "stock when the minute was written.", (0, 30, 24, 3)),
    ]
    return dashboard("fs-live-stock", "FunnelStream: Live stock monitor", panels, [store_variable()], "now-1h")
